    if is_prime(z):
        for x in range(z + 2, 800, 2):
            if is_prime(x):
                y = 1600 - z - 2 * x
                if y > x and is_prime(y):
                    # Check primes p, q, r, w
                    p = (z + x) // 2
                    q = (x + y) // 2
                    r = (y + z) // 2
                    w = x + y + z
                    if is_prime(p) and is_prime(q) and is_prime(r) and is_prime(w):
                        if p < q < r:
